import { Routes, Route } from 'react-router-dom';
import ProtectedRoute from '../Services/ProtectedRoute';
import AddExecrise from '../Pages/Admin/addExecrise';
import Exercises from '../Pages/Admin/Exercises';
import Levels from '../Pages/Admin/Levels';
import Matriel from '../Pages/Admin/Matriel';
import Unit from '../Pages/Admin/Unit';
import User from '../Pages/Admin/User';
import ExercisesUser from '../Pages/User/ExercisesUser';
import FavoritesExercise from '../Pages/User/FavoritesExercise';
import CurrentExam from '../Pages/User/CurrentExam';
import ArchivedExams from '../Pages/User/ArchivedExams';

const AppRoutes = () => {
  return (
    <Routes>
      <Route
        path="/addExercise"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <AddExecrise />
          </ProtectedRoute>
        }
      />
      <Route
        path="/"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Exercises />
          </ProtectedRoute>
        }
      />
      <Route
        path="/user"
        element={
          <ProtectedRoute allowedRoles={['user']}>
            <ExercisesUser />
          </ProtectedRoute>
        }
      />
      <Route
        path="/FavoritesExercise"
        element={
          <ProtectedRoute allowedRoles={['user']}>
            <FavoritesExercise />
          </ProtectedRoute>
        }
      />
      <Route
        path="/CurrentExam"
        element={
          <ProtectedRoute allowedRoles={['user']}>
            <CurrentExam />
          </ProtectedRoute>
        }
      />
      <Route
        path="/ArchivedExams"
        element={
          <ProtectedRoute allowedRoles={['user']}>
            <ArchivedExams />
          </ProtectedRoute>
        }
      />
      <Route
        path="/levels"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Levels />
          </ProtectedRoute>
        }
      />
      <Route
        path="/matriel"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Matriel />
          </ProtectedRoute>
        }
      />
      <Route
        path="/unit"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Unit />
          </ProtectedRoute>
        }
      />
      <Route
        path="/users"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <User />
          </ProtectedRoute>
        }
      />
    </Routes>
  );
};

export default AppRoutes;